  await withTempDir(async (dir) => {
    await fsp.writeFile(path.join(dir, 'same.txt'), 'same');
    await fsp.writeFile(path.join(dir, 'changed.txt'), 'new');
    await fsp.writeFile(path.join(dir, 'new.txt'), 'brand-new');

